  const cards = await db.card.findMany({ where: { boardId: b.id, archivedAt: null }, include: { comments: { orderBy: { createdAt: 'asc' } }, attachments: true } });
  for (const card of cards) {
    const col = b.columns.find(x => x.id === card.columnId);
    console.log('  CARD', card.id, '| col=', col?.name, '| title=', JSON.stringify(card.title));
