    for (const a of card.attachments) console.log('    ATTACH', a.id, a.filename, '->', a.storedName, a.mime, a.sizeBytes);
    for (const cm of card.comments) console.log('    COMMENT', JSON.stringify(cm.authorName), JSON.stringify(cm.body));
  }
}
await db.$disconnect();
EOF
